Update your `js/app.js` to fetch data from the API instead of using hardcoded data:

```javascript
const API_BASE = 'http://localhost:8000/api';
let allStudents = [];

// Load students from API
async function loadStudents() {
    try {
        // Show loading state
        document.getElementById('tableArea').innerHTML = `
            <div class="text-center py-5 text-muted">
                <div class="spinner-border" role="status"></div>
                <p class="mt-2">Loading students...</p>
            </div>
        `;

        const response = await fetch(`${API_BASE}/students/?limit=100`);

        if (!response.ok) {
            throw new Error(`Server returned ${response.status}`);
        }

        const data = await response.json();
        allStudents = data.results || data.data || data;

        console.log(`Loaded ${allStudents.length} students from API`);

        renderStats();
        renderTable(allStudents);

    } catch (error) {
        console.error('API Error:', error);

        // Show error message
        document.getElementById('tableArea').innerHTML = `
            <div class="alert alert-danger">
                <strong>Could not connect to API!</strong><br>
                Make sure your backend is running at ${API_BASE}<br>
                Error: ${error.message}
            </div>
        `;

        // Fall back to sample data
        allStudents = [
            { name: 'Rahul Sharma', email: 'rahul@email.com', course_name: 'Python Full Stack', city: 'Bhopal', marks: 85 },
            { name: 'Priya Patel', email: 'priya@email.com', course_name: 'Python Full Stack', city: 'Indore', marks: 92 },
        ];
        renderStats();
        renderTable(allStudents);
    }
}

// Load stats from API
async function loadStats() {
    try {
        const response = await fetch(`${API_BASE}/students/stats/`);
        if (response.ok) {
            const stats = await response.json();
            document.getElementById('totalStudents').textContent = stats.total_students;
            document.getElementById('avgMarks').textContent = stats.average_marks;
            document.getElementById('passCount').textContent = stats.pass_count;
            document.getElementById('failCount').textContent = stats.fail_count;
        }
    } catch (error) {
        console.warn('Stats API not available, calculating locally');
        renderStats();  // Calculate from loaded data
    }
}

// Update DOMContentLoaded
document.addEventListener('DOMContentLoaded', () => {
    loadStudents();
    loadStats();
});
```

Open your page and check the browser console (F12 > Console tab):
- If API is running: you should see "Loaded X students from API"
- If API is down: you should see the error message and fallback data

Also check the Network tab (F12 > Network) to see the fetch requests.

Add JWT login and authenticated CRUD operations to `js/app.js`:

```javascript
let authToken = localStorage.getItem('access_token');

// Login and get JWT token
async function login(username, password) {
    try {
        const response = await fetch(`${API_BASE}/token/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username, password }),
        });

        if (!response.ok) {
            showAlert('Invalid username or password', 'danger');
            return false;
        }

        const tokens = await response.json();
        authToken = tokens.access;
        localStorage.setItem('access_token', tokens.access);
        localStorage.setItem('refresh_token', tokens.refresh);

        showAlert('Login successful!', 'success');
        return true;
    } catch (error) {
        showAlert('Login failed: ' + error.message, 'danger');
        return false;
    }
}

// Create student (requires auth)
async function createStudent(studentData) {
    try {
        const response = await fetch(`${API_BASE}/students/`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                ...(authToken && { 'Authorization': `Bearer ${authToken}` }),
            },
            body: JSON.stringify(studentData),
        });

        if (response.status === 201) {
            const created = await response.json();
            showAlert(`Student "${created.name}" created!`, 'success');
            loadStudents();  // Reload list
            return created;
        }

        if (response.status === 401) {
            showAlert('Please log in first to add students.', 'warning');
            return null;
        }

        const errors = await response.json();
        showAlert('Validation error: ' + JSON.stringify(errors), 'danger');
        return null;
    } catch (error) {
        showAlert('Create failed: ' + error.message, 'danger');
        return null;
    }
}

// Delete student (requires auth)
async function deleteStudent(id) {
    if (!confirm('Are you sure you want to delete this student?')) return;

    try {
        const response = await fetch(`${API_BASE}/students/${id}/`, {
            method: 'DELETE',
            headers: {
                ...(authToken && { 'Authorization': `Bearer ${authToken}` }),
            },
        });

        if (response.status === 204 || response.ok) {
            showAlert('Student deleted!', 'success');
            loadStudents();
        } else if (response.status === 401) {
            showAlert('Please log in first to delete students.', 'warning');
        }
    } catch (error) {
        showAlert('Delete failed: ' + error.message, 'danger');
    }
}

// Helper: show Bootstrap alert
function showAlert(message, type) {
    const area = document.getElementById('alertArea');
    if (area) {
        area.innerHTML = `
            <div class="alert alert-${type} alert-dismissible fade show">
                ${message}
                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
            </div>
        `;
    }
}
```

