Add chart rendering in `js/app.js`:

```javascript
let marksChartInstance = null;
let cityChartInstance = null;

function renderCharts() {
    // Destroy old charts if they exist (prevents canvas reuse error)
    if (marksChartInstance) marksChartInstance.destroy();
    if (cityChartInstance) cityChartInstance.destroy();

    // Bar Chart: Top students by marks
    const sorted = [...allStudents].sort((a, b) => b.marks - a.marks).slice(0, 8);
    marksChartInstance = new Chart(document.getElementById('marksChart'), {
        type: 'bar',
        data: {
            labels: sorted.map(s => s.name.split(' ')[0]),
            datasets: [{
                label: 'Marks',
                data: sorted.map(s => s.marks),
                backgroundColor: sorted.map(s =>
                    s.marks >= 80 ? '#16a34a' :
                    s.marks >= 40 ? '#2563eb' : '#dc2626'
                ),
                borderRadius: 6,
            }],
        },
        options: {
            responsive: true,
            scales: { y: { beginAtZero: true, max: 100 } },
            plugins: { legend: { display: false } },
        },
    });

    // Doughnut Chart: City distribution
    const cityCount = {};
    allStudents.forEach(s => {
        const city = s.city || 'Unknown';
        cityCount[city] = (cityCount[city] || 0) + 1;
    });

    cityChartInstance = new Chart(document.getElementById('cityChart'), {
        type: 'doughnut',
        data: {
            labels: Object.keys(cityCount),
            datasets: [{
                data: Object.values(cityCount),
                backgroundColor: ['#2563eb', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'],
            }],
        },
        options: {
            responsive: true,
            plugins: { legend: { position: 'bottom' } },
        },
    });
}
```

Call `renderCharts()` after loading students — add it to your `loadStudents()` function after `renderTable()`:

```javascript
renderStats();
renderTable(allStudents);
renderCharts();   // Add this line
```

Check your page — you should see a bar chart and a doughnut chart side by side.

